<div class="nl-page"><div class="nl-page-head"><p class="nl-kicker">정책 자료</p><h1>정책 뉴스</h1><p>공식기관 자료와 언론기사를 모아 정책 흐름을 빠르게 확인합니다.</p></div><?php if(nl_can('news_manage')){ ?><div class="nl-actions nl-actions--bottom"><a class="nl-btn" href="<?php echo nl_url('news-manage.php'); ?>">뉴스 관리</a></div><?php } ?><div class="nl-news-list"><?php if(!$rows)echo '<div class="nl-empty">등록된 뉴스가 없습니다.</div>';foreach($rows as $r){$url=nl_safe_external_url($r['source_url']);if(!$url)continue;?><a class="nl-news-row" href="<?php echo nl_h($url); ?>" target="_blank" rel="noopener noreferrer"><span><strong><?php echo nl_h($r['title']); ?></strong><small class="nl-news-meta"><?php echo nl_h(trim(($r['source_name']?:'출처').' · '.($r['category']?:$r['content_type']))); ?></small></span><span><?php echo nl_h($r['published_at']?substr($r['published_at'],0,10):''); ?></span></a><?php } ?></div></div>
